"""Scratch diagnostic, not a supported Dewy backend. Reject unknown IR explicitly."""
import ast,collections,json,sys
from pathlib import Path
base=Path(__file__).resolve().parent
source=Path(sys.argv[1]) if len(sys.argv)>1 else base/'compiler.ir'
out=base/'c';out.mkdir(exist_ok=True)
fs=[];f=None
for line in source.open():
 key,_,s=line.strip().partition(' ')
 if key=='FN':
  idx,n,ret=map(int,s.split());f=dict(idx=idx,n=n,ret=ret,code=[]);fs.append(f)
 elif key in ('VT','KV','SS','SA','ARGS'):f[key]=json.loads(s)
 elif key=='NAME':f['name']=s
 elif key=='I':
  op,*fields=s.split();f['code'].append((op,*map(int,fields)))
 elif key=='META':size,main,mc,end,mt=s.split();size,main,end,mt=map(int,(size,main,end,mt))
 elif key=='ROOTS':roots=json.loads(s)
 elif key=='DATA':data=json.loads(s)
 elif key not in ('END',''):raise ValueError(line[:120])
types={-1:'void',0:'U',1:'double',2:'float',3:'U'}
def sig(f):return f"{types[f['ret']]} f{f['idx']}({', '.join(types[t]+' v'+str(i) for i,t in enumerate(f['VT'][:f['n']])) or 'void'})"
def u(x):return f'UINT64_C({x&((1<<64)-1)})'
header='''#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <math.h>
typedef uint64_t U;
typedef int64_t S;
extern unsigned char gd[], rd[];
extern U initial_stack;
static inline U sc(U n,U a,U b,U c,U d,U e,U f){
 register U r10 __asm__("r10")=d, r8 __asm__("r8")=e, r9 __asm__("r9")=f;
 U r; __asm__ volatile("syscall":"=a"(r):"a"(n),"D"(a),"S"(b),"d"(c),"r"(r10),"r"(r8),"r"(r9):"rcx","r11","memory"); return r;
}
extern U probe_setjmp(U) __attribute__((returns_twice));
extern U probe_longjmp(U,U) __attribute__((noreturn));
extern U probe_stack(void);
static inline U f2i(double x){return isnan(x)?0:x>=0x1p63?INT64_MAX:x<=-0x1p63?(U)INT64_MIN:(U)(S)x;}
static inline U sdiv(U a,U b){if(!b||(a==(U)INT64_MIN&&b==UINT64_MAX))__builtin_trap();return (S)a/(S)b;}
static inline U srem(U a,U b){if(!b||(a==(U)INT64_MIN&&b==UINT64_MAX))__builtin_trap();return (S)a%(S)b;}
static inline U udiv(U a,U b){if(!b)__builtin_trap();return a/b;}
static inline U urem(U a,U b){if(!b)__builtin_trap();return a%b;}
'''
for typ in ['uint8_t','uint16_t','uint32_t','uint64_t','int8_t','int16_t','int32_t','int64_t','float','double']:
 header+=f'static inline {typ} ld_{typ}(U p){{{typ} x;memcpy(&x,(void*)p,sizeof x);return x;}}\n'
 header+=f'static inline void st_{typ}(U p,{typ} x){{memcpy((void*)p,&x,sizeof x);}}\n'
header+='''static inline double bf64(U x){double r;memcpy(&r,&x,8);return r;}
static inline float bf32(U x){uint32_t b=x;float r;memcpy(&r,&b,4);return r;}
static inline U fb64(double x){U r;memcpy(&r,&x,8);return r;}
static inline U fb32(float x){uint32_t r;memcpy(&r,&x,4);return r;}
static inline U streq(U a,U b){if(a==b)return 1;U an=a?ld_uint64_t(a+8):0,bn=b?ld_uint64_t(b+8):0;return an==bn&&(!an||memcmp((void*)(a+24),(void*)(b+24),an)==0);}
'''
header+='\n'.join(sig(f)+';' for f in fs)+'\n'
(out/'probe.h').write_text(header)
byidx={f['idx']:f for f in fs}
ops=collections.Counter()
def translate(f):
 vt=f['VT'];kv=f['KV'];args=f['ARGS'];ctl=[];lines=[f'// {f["name"]}',sig(f)+'{']
 def v(i):
  assert i>=0,(f['name'],i)
  return u(kv[i]) if vt[i]==3 else 'v'+str(i)
 for i,t in enumerate(vt):
  if i>=f['n'] and t!=3:lines.append(f'{types[t]} v{i};')
 for i,(sz,al) in enumerate(zip(f['SS'],f['SA'])):lines.append(f'_Alignas({al}) unsigned char s{i}[{max(sz,1)}];')
 for p,(op,ty,d,a,b,c,imm) in enumerate(f['code']):
  ops[op]+=1;expr=None;stmt=None
  def va():return v(a)
  def vb():return v(b)
  def dest():return v(d)
  if op in ('nop','assume'):continue
  elif op=='iconst':expr=u(imm)
  elif op=='fconst':expr=f'bf{32 if ty==2 else 64}({u(imm)})'
  elif op=='mov':expr=va()
  elif op in ('add','sub','mul','and_','or_','xor','eq','ne'):
   sym=dict(add='+',sub='-',mul='*',and_='&',or_='|',xor='^',eq='==',ne='!=')[op];expr=f'{va()} {sym} {vb()}'
  elif op in ('lts','les','gts','ges','ltu','leu','gtu','geu'):
   sym=dict(lt='<',le='<=',gt='>',ge='>=')[op[:2]];cast='(S)' if op[-1]=='s' else ''
   expr=f'{cast}{va()} {sym} {cast}{vb()}'
  elif op in ('shl','shrs','shru'):expr=f'{"(S)" if op=="shrs" else ""}{va()} {"<<" if op=="shl" else ">>"} ({vb()} & 63)'
  elif op in ('divs','divu','rems','remu'):expr=f'{dict(divs="sdiv",divu="udiv",rems="srem",remu="urem")[op]}({va()},{vb()})'
  elif op in ('mulhs','mulhu'):expr=f'(({"__int128" if op=="mulhs" else "unsigned __int128"}){"(S)" if op=="mulhs" else ""}{va()} * {"(S)" if op=="mulhs" else ""}{vb()}) >> 64'
  elif op in ('neg','not_'):expr=f'{"-" if op=="neg" else "~"}{va()}'
  elif op.startswith(('sext','zext')):expr=f'({"int" if op[0]=="s" else "uint"}{op[4:]}_t){va()}'
  elif op in ('fadd','fsub','fmul','fdiv','feq','fne','flt','fle','fgt','fge'):
   sym=dict(fadd='+',fsub='-',fmul='*',fdiv='/',feq='==',fne='!=',flt='<',fle='<=',fgt='>',fge='>=')[op];expr=f'{va()} {sym} {vb()}'
  elif op=='fneg':expr=f'-{va()}'
  elif op in ('fsqrt','ffloor','fceil','fabs','ftrunc'):expr=f'{op[1:]}{"f" if ty==2 else ""}({va()})'
  elif op in ('fmin','fmax'):expr=f'{va()} {"<" if op=="fmin" else ">"} {vb()} ? {va()} : {vb()}'
  elif op in ('i2f','u2f','f2f'):expr=f'({types[ty]}){"(S)" if op=="i2f" else ""}{va()}'
  elif op=='f2i':expr=f'f2i({va()})'
  elif op=='bits2f':expr=f'bf{32 if ty==2 else 64}({va()})'
  elif op=='f2bits':expr=f'fb{32 if ty==2 else 64}({va()})'
  elif op in ('load','store'):
   sz=c&15;t=('float' if sz==4 else 'double') if c&32 else ('int' if c&16 and op=='load' else 'uint')+str(sz*8)+'_t'
   addr=f'{va()}+{u(imm)}'
   if c&128:addr+=f'+({v(b if op=="load" else d)}<<{(c>>8)&3})'
   if op=='load':expr=f'ld_{t}({addr})'
   else:stmt=f'st_{t}({addr},{vb()});'
  elif op=='slot':expr=f'(U)s{a}'
  elif op in ('gaddr','daddr'):expr=f'(U)({"gd" if op=="gaddr" else "rd"}+{imm})'
  elif op=='faddr':expr=f'(U)f{imm}'
  elif op in ('copy','memcpy'):stmt=f'memcpy((void*){va()},(void*){vb()},{imm if op=="copy" else v(c)});'
  elif op in ('zero','memset'):stmt=f'memset((void*){va()},{0 if op=="zero" else vb()},{imm if op=="zero" else v(c)});'
  elif op=='zeroslots':
   stmt=' '.join(f'v{x>>1}=0;' if x&1 else f'memset(s{x>>1},0,sizeof s{x>>1});' for x in args[a:a+b])
  elif op=='memeq':expr=f'((S){v(c)}<=0 || !memcmp((void*){va()},(void*){vb()},{v(c)}))'
  elif op=='streq':expr=f'streq({va()},{vb()})'
  elif op in ('call','calli','callc','syscall','intr'):
   av=args[a:a+b];values=[v(x) for x in av];vs=','.join(values)
   if op=='call':
    assert c in (0,1,2),c
    assert imm in byidx,(f['name'],imm)
    expr=f'f{imm}({vs})'
   elif op in ('calli','callc'):
    ts=','.join(types[vt[x]] for x in av) or 'void'
    expr=f'(({types[ty]} (*)({ts})){v(c)})({vs})'
   elif op=='syscall':expr='sc('+','.join(values+['0']*(7-len(values)))+')'
   elif imm==1:expr='initial_stack'
   elif imm==2:expr=f'probe_setjmp({vs})'
   elif imm==3:expr=f'probe_longjmp({vs})'
   elif imm==6:expr=f'__atomic_fetch_add((U*){values[0]},{values[1]},__ATOMIC_SEQ_CST)'
   elif imm==7:
    stmt=f'{{U expected={values[1]};__atomic_compare_exchange_n((U*){values[0]},&expected,{values[2]},0,__ATOMIC_SEQ_CST,__ATOMIC_SEQ_CST);{dest()}=expected;}}'
   elif imm==8:expr='probe_stack()'
   else:raise ValueError(('intr',imm))
   if expr and (d<0 or ty<0):stmt=expr+';';expr=None
  elif op in ('block','loop','if_'):
   ctl.append((op,p))
   if op=='loop':stmt=f'L{p}:;'
   elif op=='if_':stmt=f'if(!{va()})goto E{p};'
  elif op=='else_':
   kind,q=ctl[-1];assert kind=='if_';ctl[-1]=('else_',q);stmt=f'goto X{q}; E{q}:;'
  elif op=='end':
   kind,q=ctl.pop();stmt=(f'E{q}:;' if kind=='if_' else '')+f'X{q}:;'
  elif op in ('br','brif','brtable'):
   def target(depth):
    k,q=ctl[-1-depth];return ('L' if k=='loop' else 'X')+str(q)
   if op=='br':stmt=f'goto {target(imm)};'
   elif op=='brif':stmt=f'if({va()})goto {target(imm)};'
   else:stmt='switch('+va()+'){'+''.join(f'case {k}:goto {target(depth)};' for k,depth in enumerate(args[c:c+b]))+f'default:goto {target(imm)};'+'}'
  elif op=='ret':stmt='return'+(' '+va() if a>=0 and f['ret']>=0 else '')+';'
  elif op=='trap':stmt='__builtin_trap();'
  elif op=='select':expr=f'{va()} ? {vb()} : {v(c)}'
  else:raise ValueError(op)
  if expr is not None:
   # VK has no writable location; an iconst can remain after propagation.
   if vt[d]!=3:lines.append(f'{dest()}={expr};')
  elif stmt is not None:lines.append(stmt)
 assert not ctl
 lines+=['__builtin_unreachable();','}']
 return '\n'.join(lines)+'\n'
chunks=[];body='';ins=0
for f in fs:
 body+=translate(f);ins+=len(f['code'])
 if ins>=15000:
  p=out/f'unit{len(chunks)}.c';p.write_text('#include "probe.h"\n'+body);chunks.append(p.name);body='';ins=0
if body:
 p=out/f'unit{len(chunks)}.c';p.write_text('#include "probe.h"\n'+body);chunks.append(p.name)
runtime='#include "probe.h"\n_Alignas(64) unsigned char gd['+str(size+8)+'];\n_Alignas(64) unsigned char rd[]={'+','.join(map(str,data))+'};\nU initial_stack;\n'
runtime+='void probe_entry(U stack){initial_stack=stack;st_uint64_t((U)gd,stack);'+''.join(f'f{x}();' for x in roots)
runtime+=('U status=' if mc=='true' else '')+f'f{main}();'
if end>=0:runtime+=f'f{end}();'
runtime+='sc(231,'+('status' if mc=='true' else '0')+',0,0,0,0,0);__builtin_unreachable();}\n'
(out/'runtime.c').write_text(runtime);chunks.append('runtime.c')
(out/'start.S').write_text(''' .text
.global _start
_start:
 mov %rsp,%rdi
 and $-16,%rsp
 call probe_entry
 ud2
.global probe_setjmp
probe_setjmp:
 mov %rbx,0(%rdi)
 mov %rbp,8(%rdi)
 mov %r12,16(%rdi)
 mov %r13,24(%rdi)
 mov %r14,32(%rdi)
 mov %r15,40(%rdi)
 lea 8(%rsp),%rax
 mov %rax,48(%rdi)
 mov (%rsp),%rax
 mov %rax,56(%rdi)
 xor %eax,%eax
 ret
.global probe_longjmp
probe_longjmp:
 mov 0(%rdi),%rbx
 mov 8(%rdi),%rbp
 mov 16(%rdi),%r12
 mov 24(%rdi),%r13
 mov 32(%rdi),%r14
 mov 40(%rdi),%r15
 mov 48(%rdi),%rsp
 mov %rsi,%rax
 jmp *56(%rdi)
.global probe_stack
probe_stack:
 lea 8(%rsp),%rax
 ret
.section .note.GNU-stack,"",@progbits
''')
(out/'manifest.json').write_text(json.dumps({'units':chunks,'functions':len(fs),'ops':ops,'source':str(source)},indent=2)+'\n')
print(len(fs),'functions;',len(chunks),'C units;',sum(ops.values()),'IR instructions')

